-- Fresh dedicated identity database; never apply to an unrelated application's database.
IF OBJECT_ID('dbo.accounts') IS NULL CREATE TABLE dbo.accounts (id NVARCHAR(64) PRIMARY KEY,email NVARCHAR(320) NOT NULL UNIQUE,email_verified BIT NOT NULL DEFAULT 0,display_name NVARCHAR(80) NOT NULL,password_hash NVARCHAR(500) NULL,state NVARCHAR(16) NOT NULL CHECK(state IN('active','suspended','deleted')),lang NVARCHAR(16) NOT NULL DEFAULT 'pt-BR',timezone NVARCHAR(64) NOT NULL DEFAULT 'America/Sao_Paulo',marketing_opt_in BIT NOT NULL DEFAULT 0,age_confirmed_at BIGINT NOT NULL,created_at BIGINT NOT NULL,updated_at BIGINT NOT NULL,avatar_url NVARCHAR(MAX) NULL);
IF COL_LENGTH('dbo.accounts','avatar_url') IS NULL ALTER TABLE dbo.accounts ADD avatar_url NVARCHAR(MAX) NULL;
-- avatar_url widened from NVARCHAR(2048): a preset path is short, but an uploaded
-- photo is stored as a bounded data: URI (AVATAR_DATA_URI_MAX in core.py), which
-- needs NVARCHAR(MAX). Run once more if an earlier deploy created the narrower column.
IF EXISTS (SELECT 1 FROM sys.columns WHERE object_id = OBJECT_ID('dbo.accounts') AND name = 'avatar_url' AND max_length <> -1)
    ALTER TABLE dbo.accounts ALTER COLUMN avatar_url NVARCHAR(MAX) NULL;
IF OBJECT_ID('dbo.email_verifications') IS NULL CREATE TABLE dbo.email_verifications (id NVARCHAR(64) PRIMARY KEY,account_id NVARCHAR(64) NOT NULL REFERENCES accounts(id),token_hash NVARCHAR(64) NOT NULL UNIQUE,expires_at BIGINT NOT NULL,used_at BIGINT NULL,created_at BIGINT NOT NULL);
IF OBJECT_ID('dbo.oauth_identities') IS NULL CREATE TABLE dbo.oauth_identities (provider NVARCHAR(32) NOT NULL,subject NVARCHAR(256) NOT NULL,account_id NVARCHAR(64) NOT NULL REFERENCES accounts(id),created_at BIGINT NOT NULL,CONSTRAINT pk_oauth PRIMARY KEY(provider,subject),CONSTRAINT uq_oauth_account UNIQUE(provider,account_id));
IF OBJECT_ID('dbo.oauth_nonces') IS NULL CREATE TABLE dbo.oauth_nonces (state NVARCHAR(128) PRIMARY KEY,nonce NVARCHAR(128) NOT NULL,verifier NVARCHAR(128) NOT NULL,browser_hash NVARCHAR(64) NOT NULL,consent_json NVARCHAR(MAX) NOT NULL,expires_at BIGINT NOT NULL);
IF OBJECT_ID('dbo.sessions') IS NULL CREATE TABLE dbo.sessions (id NVARCHAR(64) PRIMARY KEY,account_id NVARCHAR(64) NOT NULL REFERENCES accounts(id),token_hash NVARCHAR(64) NOT NULL UNIQUE,created_at BIGINT NOT NULL,expires_at BIGINT NOT NULL,revoked_at BIGINT NULL);
IF OBJECT_ID('dbo.wallets') IS NULL CREATE TABLE dbo.wallets (account_id NVARCHAR(64) PRIMARY KEY REFERENCES accounts(id),available INT NOT NULL DEFAULT 0 CHECK(available>=0),reserved INT NOT NULL DEFAULT 0 CHECK(reserved>=0));
IF OBJECT_ID('dbo.preferences_bookmarks') IS NULL CREATE TABLE dbo.preferences_bookmarks (account_id NVARCHAR(64) PRIMARY KEY REFERENCES accounts(id),interests NVARCHAR(MAX) NOT NULL DEFAULT '[]',saved NVARCHAR(MAX) NOT NULL DEFAULT '[]',opened NVARCHAR(MAX) NOT NULL DEFAULT '[]');
IF OBJECT_ID('dbo.missions') IS NULL CREATE TABLE dbo.missions (id NVARCHAR(64) NOT NULL,version INT NOT NULL CHECK(version>0),award INT NOT NULL CHECK(award>0 AND award<=500),starts_at BIGINT NOT NULL,ends_at BIGINT NOT NULL,active BIT NOT NULL DEFAULT 0,verifier NVARCHAR(16) NOT NULL CHECK(verifier IN('quiz','interests')),definition_json NVARCHAR(MAX) NOT NULL,coverage_reference NVARCHAR(200) NOT NULL,CONSTRAINT pk_missions PRIMARY KEY(id,version),CONSTRAINT ck_missions_period CHECK(ends_at>starts_at));
IF OBJECT_ID('dbo.challenges') IS NULL CREATE TABLE dbo.challenges (id NVARCHAR(64) PRIMARY KEY,browser_hash NVARCHAR(64) NOT NULL,account_id NVARCHAR(64) NULL REFERENCES accounts(id),mission_id NVARCHAR(64) NOT NULL,mission_version INT NOT NULL,definition_hash NVARCHAR(64) NOT NULL,expires_at BIGINT NOT NULL,used_at BIGINT NULL,CONSTRAINT fk_challenge_mission FOREIGN KEY(mission_id,mission_version) REFERENCES missions(id,version));
IF OBJECT_ID('dbo.mission_evidence') IS NULL CREATE TABLE dbo.mission_evidence (id NVARCHAR(64) PRIMARY KEY,challenge_id NVARCHAR(64) NOT NULL UNIQUE REFERENCES challenges(id),browser_hash NVARCHAR(64) NOT NULL,account_id NVARCHAR(64) NULL REFERENCES accounts(id),mission_id NVARCHAR(64) NOT NULL,mission_version INT NOT NULL,payload NVARCHAR(MAX) NOT NULL,created_at BIGINT NOT NULL,CONSTRAINT fk_evidence_mission FOREIGN KEY(mission_id,mission_version) REFERENCES missions(id,version));
IF OBJECT_ID('dbo.pending_rewards') IS NULL CREATE TABLE dbo.pending_rewards (id NVARCHAR(64) PRIMARY KEY,token_hash NVARCHAR(64) NOT NULL UNIQUE,browser_hash NVARCHAR(64) NOT NULL,evidence_id NVARCHAR(64) NOT NULL REFERENCES mission_evidence(id),expires_at BIGINT NOT NULL,claimed_at BIGINT NULL,claimed_by NVARCHAR(64) NULL REFERENCES accounts(id));
IF OBJECT_ID('dbo.completions') IS NULL CREATE TABLE dbo.completions (id NVARCHAR(64) PRIMARY KEY,account_id NVARCHAR(64) NOT NULL REFERENCES accounts(id),mission_id NVARCHAR(64) NOT NULL,mission_version INT NOT NULL,evidence_ref NVARCHAR(64) NOT NULL REFERENCES mission_evidence(id),created_at BIGINT NOT NULL,CONSTRAINT uq_completion UNIQUE(account_id,mission_id,mission_version),CONSTRAINT fk_completion_mission FOREIGN KEY(mission_id,mission_version) REFERENCES missions(id,version));
IF OBJECT_ID('dbo.ledger') IS NULL CREATE TABLE dbo.ledger (id NVARCHAR(64) PRIMARY KEY,account_id NVARCHAR(64) NOT NULL REFERENCES accounts(id),available_delta INT NOT NULL,reserved_delta INT NOT NULL,reason NVARCHAR(32) NOT NULL,reference_id NVARCHAR(64) NOT NULL,created_at BIGINT NOT NULL,CONSTRAINT uq_ledger UNIQUE(reason,reference_id));
IF OBJECT_ID('dbo.requests') IS NULL CREATE TABLE dbo.requests (account_id NVARCHAR(64) NOT NULL REFERENCES accounts(id),request_key NVARCHAR(128) NOT NULL,payload_hash NVARCHAR(64) NOT NULL,result_id NVARCHAR(64) NOT NULL,CONSTRAINT pk_requests PRIMARY KEY(account_id,request_key));
IF OBJECT_ID('dbo.rate_limits') IS NULL CREATE TABLE dbo.rate_limits (scope NVARCHAR(64) NOT NULL,bucket NVARCHAR(64) NOT NULL,window_start BIGINT NOT NULL,count INT NOT NULL,CONSTRAINT pk_rate_limits PRIMARY KEY(scope,bucket));
IF OBJECT_ID('dbo.consents') IS NULL CREATE TABLE dbo.consents (id NVARCHAR(64) PRIMARY KEY,account_id NVARCHAR(64) NOT NULL REFERENCES accounts(id),purpose NVARCHAR(64) NOT NULL,version NVARCHAR(32) NOT NULL,granted BIT NOT NULL,created_at BIGINT NOT NULL);
IF OBJECT_ID('dbo.tr_ledger_no_update') IS NULL EXEC('CREATE TRIGGER dbo.tr_ledger_no_update ON dbo.ledger INSTEAD OF UPDATE AS BEGIN THROW 51001, ''append-only ledger'', 1; END');
IF OBJECT_ID('dbo.tr_ledger_no_delete') IS NULL EXEC('CREATE TRIGGER dbo.tr_ledger_no_delete ON dbo.ledger INSTEAD OF DELETE AS BEGIN THROW 51001, ''append-only ledger'', 1; END');

-- Clerk identities: CPF is keyed, never stored as plaintext or public metadata.
IF OBJECT_ID('dbo.managed_identities') IS NULL CREATE TABLE dbo.managed_identities (subject NVARCHAR(128) PRIMARY KEY,account_id NVARCHAR(64) NOT NULL UNIQUE REFERENCES accounts(id),created_at BIGINT NOT NULL);
IF OBJECT_ID('dbo.managed_profiles') IS NULL CREATE TABLE dbo.managed_profiles (account_id NVARCHAR(64) PRIMARY KEY REFERENCES accounts(id),cpf_fingerprint NVARCHAR(64) NOT NULL UNIQUE,cpf_last_two NVARCHAR(2) NOT NULL,birth_date NVARCHAR(10) NOT NULL);
IF OBJECT_ID('dbo.managed_bans') IS NULL CREATE TABLE dbo.managed_bans (cpf_fingerprint NVARCHAR(64) PRIMARY KEY,email_fingerprint NVARCHAR(64) NOT NULL,account_id NVARCHAR(64) NOT NULL REFERENCES accounts(id),created_at BIGINT NOT NULL);
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE name='managed_bans_email' AND object_id=OBJECT_ID('dbo.managed_bans')) CREATE INDEX managed_bans_email ON dbo.managed_bans(email_fingerprint);
IF OBJECT_ID('dbo.managed_audit') IS NULL CREATE TABLE dbo.managed_audit (id NVARCHAR(64) PRIMARY KEY,account_id NVARCHAR(64) NOT NULL REFERENCES accounts(id),actor NVARCHAR(128) NOT NULL,action NVARCHAR(32) NOT NULL,reason NVARCHAR(500) NOT NULL,created_at BIGINT NOT NULL);
IF OBJECT_ID('dbo.managed_deletions') IS NULL CREATE TABLE dbo.managed_deletions (account_id NVARCHAR(64) PRIMARY KEY REFERENCES accounts(id),subject NVARCHAR(128) NOT NULL,requested_at BIGINT NOT NULL,completed_at BIGINT NULL);

IF OBJECT_ID('dbo.managed_webhook_receipts') IS NULL CREATE TABLE dbo.managed_webhook_receipts (message_id NVARCHAR(128) PRIMARY KEY,event_type NVARCHAR(64) NOT NULL,received_at BIGINT NOT NULL);
